int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !pkey) {
        return -1;
    }

    md = EVP_get_digestbyname(OBJ_nid2ln(a->algorithm->nid));
    if (!md) {
        return -1;
    }

    ctx = EVP_MD_CTX_new();
    if (!ctx) {
        goto err;
    }

    if (!EVP_VerifyInit_ex(ctx, md, NULL, pkey, NULL)) {
        goto err;
    }

    if (!ASN1_item_digest(it, md, asn, NULL, EVP_DigestUpdate, ctx)) {
        goto err;
    }

    if (!EVP_VerifyFinal(ctx, signature->data, (size_t)signature->length, pkey)) {
        ret = 0;
        goto err;
    }

    ret = 1;

err:
    if (ctx) {
        EVP_MD_CTX_free(ctx);
    }
    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *md_ctx = NULL;
    const EVP_MD *digest = NULL;
    int ret = -1;
    unsigned char *sig = NULL;
    int siglen = 0;

    if (!a || !signature || !asn || !pkey)
        return -1;

    if (a->parameter) {
        ASN1_OBJECT *obj = a->parameter->value.ptr;
        if (OBJ_obj2nid(obj) != NID_undef)
            digest = EVP_get_digestbyname(OBJ_nid2ln(OBJ_obj2nid(obj)));
    }

    if (!digest) {
        ASN1err(ASN1_F_VERIFY_ASN1_SIGNATURE, ASN1_R_UNKNOWN_DIGEST_ALGORITHM);
        return -1;
    }

    if (!(md_ctx = EVP_MD_CTX_new()))
        goto err;

    if (!EVP_DigestVerifyInit(md_ctx, NULL, digest, NULL, pkey))
        goto err;

    if (!EVP_DigestVerifyUpdate(md_ctx, asn, it->it->size))
        goto err;

    if ((siglen = signature->length) <= 0)
        goto err;

    sig = signature->data;

    if ((ret = EVP_DigestVerifyFinal(md_ctx, sig, siglen)) <= 0)
        ASN1err(ASN1_F_VERIFY_ASN1_SIGNATURE, ASN1_R_BAD_SIGNATURE);

err:
    if (md_ctx)
        EVP_MD_CTX_free(md_ctx);
    return ret;
}

int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *ctx = NULL;
    const EVP_MD *md = NULL;
    int ret = -1;

    if (!a || !signature || !pkey || !asn) {
        return -1;
    }

    if (!OBJ_obj2nid(a->algorithm)) {
        return -1;
    }

    md = EVP_get_digestbynid(OBJ_obj2nid(a->algorithm));
    if (!md) {
        return -1;
    }

    ctx = EVP_MD_CTX_new();
    if (!ctx) {
        goto err;
    }

    if (!EVP_DigestVerifyInit(ctx, NULL, md, NULL, pkey)) {
        goto err;
    }

    if (it && it->s1) {
        ASN1_TYPE *at = NULL;
        if ((at = ASN1_ITEM_d2i(NULL, &asn, it)) == NULL) {
            goto err;
        }

        if (!EVP_DigestUpdate(ctx, at->value.ptr, at->length)) {
            goto err;
        }

        ASN1_TYPE_free(at);
    }

    if (!EVP_DigestVerifyFinal(ctx, signature->data, signature->length)) {
        ret = 0;
        goto err;
    }

    ret = 1;

err:
    if (ctx) {
        EVP_MD_CTX_free(ctx);
    }

    return ret;
}

