int verify_asn1_signature(const ASN1_ITEM *it, X509_ALGOR *a, ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey) {
    EVP_MD_CTX *md_ctx = NULL;
    const EVP_MD *evp_md = NULL;
    unsigned char *sig_bytes = NULL;
    int sig_len = 0;
    int ret = -1;

    if (!a || !signature || !asn || !pkey) {
        return -1;
    }

    if (!a->parameter || !EVP_PKEY_type(EVP_PKEY_get_base_id(pkey))) {
        return -1;
    }

    evp_md = EVP_get_digestbynid(a->algorithm);
    if (!evp_md) {
        return -1;
    }

    sig_len = (int)signature->length;
    if (sig_len <= 0) {
        return -1;
    }

    sig_bytes = OPENSSL_malloc(sig_len);
    if (!sig_bytes) {
        return -1;
    }

    memcpy(sig_bytes, signature->data, sig_len);

    md_ctx = EVP_MD_CTX_new();
    if (!md_ctx) {
        goto err;
    }

    if (!EVP_VerifyInit_ex(md_ctx, evp_md, NULL)) {
        goto err;
    }

    if (!EVP_VerifyUpdate(md_ctx, asn, it->it->size_func(asn))) {
        goto err;
    }

    if (!EVP_VerifyFinal(md_ctx, sig_bytes, sig_len, pkey)) {
        ret = 0;
    } else {
        ret = 1;
    }

err:
    if (md_ctx) {
        EVP_MD_CTX_free(md_ctx);
    }
    if (sig_bytes) {
        OPENSSL_free(sig_bytes);
    }

    return ret;
}
